{"implementation": "import math
def solve(case):
    matrix = case['matrix']
    if not matrix or not isinstance(matrix, list) or not all(isinstance(row, list) for row in matrix):
        raise ValueError('Invalid matrix')
    n_rows = len(matrix)
    n_cols = len(matrix[0])
    if n_cols == 0:
        raise ValueError('Empty columns')
    if not all(len(row) == n_cols for row in matrix):
        raise ValueError('Rows have different lengths')
    doc_freq = [0] * n_cols
    for row in matrix:
        for j, val in enumerate(row):
            if val != 0:
                doc_freq[j] += 1
    idf = [math.log(1 + n_rows / (1 + freq)) for freq in doc_freq]
    idf_rounded = [round(x, 6) for x in idf]
    weighted_matrix = []
    row_degrees = []
    for row in matrix:
        weighted_row = [round(row[j] * idf[j], 6) for j in range(n_cols)]
        weighted_matrix.append(weighted_row)
        row_degrees.append(round(sum(weighted_row), 6))
    return {'idf': idf_rounded, 'weighted_matrix': weighted_matrix, 'row_degrees': row_degrees}
"}
